(function(){
  function v(id){var n=parseFloat(document.getElementById(id).value);return isNaN(n)||n<0?0:n;}
  function fee(net){var t=[[750000,1/3],[750000,.30],[750000,.25],[750000,.20]],f=0,r=net;for(var i=0;i<t.length&&r>0;i++){var p=Math.min(r,t[i][0]);f+=p*t[i][1];r-=p;}return {f:f,over:r};}
  function m(x){return '$'+Math.round(x).toLocaleString('en-US');}
  function run(){var net=Math.max(0,v('g')-v('c')),fe=fee(net),after=net-fe.f-v('l'),home=after-v('a');
    var s='Net recovery '+m(net)+', maximum fee '+m(fe.f)+(fe.over>0?' (plus a court-approved fee on '+m(fe.over)+' above $3,000,000)':'')+', after liens '+m(after)+', after catching up the mortgage '+m(home)+'.';
    if(home<0){s+=' The settlement alone would not clear the arrears, so ask about a modification or repayment plan now.';}
    document.getElementById('out').textContent=s;}
  ['g','c','l','a'].forEach(function(id){document.getElementById(id).addEventListener('input',run);});
})();
